package main

import (
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

func TestNotes(t *testing.T) {
	now := time.Unix(0, 0)
	h := newHandler(func() time.Time { return now })
	for _, tc := range []struct {
		at                 int
		method, path, body string
		status             int
		want               string
	}{
		{0, "GET", "/notes", "", 200, "[]"},
		{1, "POST", "/notes", `{"text":"hello"}`, 201, `{"id":1,"text":"hello"}`},
		{2, "POST", "/notes", `{"text":"world"}`, 201, `{"id":2,"text":"world"}`},
		{3, "POST", "/notes", `{"text":" "}`, 400, ""},
		{4, "POST", "/notes", `{"text":"x"} {}`, 400, ""},
		{5, "POST", "/notes", strings.Repeat("x", 65537), 400, ""},
		{6, "GET", "/notes", "", 200, `[{"id":1,"text":"hello"},{"id":2,"text":"world"}]`},
		{7, "DELETE", "/notes", "", 405, ""},
		{7, "GET", "/missing", "", 404, ""},
		{7, "POST", "/notes", `{"text":"blocked"}`, 429, ""},
		{7, "GET", "/notes", "", 429, ""},
		{8, "GET", "/notes", "", 200, `[{"id":1,"text":"hello"},{"id":2,"text":"world"}]`},
	} {
		now = time.Unix(0, int64(tc.at)*int64(100*time.Millisecond))
		w := httptest.NewRecorder()
		h.ServeHTTP(w, httptest.NewRequest(tc.method, tc.path, strings.NewReader(tc.body)))
		if tc.status == 429 && w.Header().Get("Retry-After") != "1" {
			t.Error("missing Retry-After: 1")
		}
		if w.Code != tc.status || (tc.want != "" && strings.TrimSpace(w.Body.String()) != tc.want) {
			t.Errorf("%s %s: got %d %s, want %d %s", tc.method, tc.path, w.Code, w.Body.String(), tc.status, tc.want)
		}
	}
}
